            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-n"))) {
            if (i + 1 >= args.len) {
                std.debug.print("fx-top: option '-n' requires a value\n", .{});
                return error.MissingValue;
