            };
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-m"))) {
            o.sort = .Mem;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "--rows"))) {
            o.rows = true;
            matched = true;
        }
        if (!matched) {
            if (a.len > 1 and a[0] == '-') {
                std.debug.print("fx-top: unknown option '{s}'\n", .{ a });
                return error.UnknownOption;
